with unpacked as (select id, created_at, coalesce(ship_to.city, 'UNKNOWN') as city_or_unknown, size(filter(items, li -> li.qty >= 3)) as bulk_lines, ship_to.country as ship_country, forall(items, li -> li.qty <= 5) as all_small_qty, exists(items, li -> li.price > 100) as has_premium_item from carts) select id, created_at, city_or_unknown, ship_country, has_premium_item, sum(bulk_lines) over w_part cumulative_bulk_lines, sum(bulk_lines) over (partition by year(created_at) order by cast(created_at as bigint) range between 900 preceding and current row) bulk_lines_sum_15m, row_number() over w_recent seq_no, sum(bulk_lines) over w_part running_bulk_lines, lag(bulk_lines, 1) over (partition by ship_country order by bulk_lines, id) prev_bulk_lines from unpacked window w_part as (partition by ship_country order by created_at, id rows between unbounded preceding and current row), w_recent as (partition by ship_country order by created_at desc, id);
